pt_d":"調查研究法","answer":"B","exp_why":null,"exp_others":null,"exp_trap":null,"exp_raw":null,"mnemonic":null,"extension":null,"law":null,"mistake":null,"source_exam_code":"111110","source_url":"https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?c=105&code=111110&q=1&s=0406&t=Q","analysis_status":"review","analysis_attempts":0,"analysis_error":null,"analysis_started_at":null,"analysis_completed_at":null,"legal_status":"not_applicable","legal_checked_at":null,"legal_note":null,"legal_source_url":null,"legal_canonical_names":[],"accepted_answers":null,"grading_mode":"standard","analysis_last_attempt_at":null},{"id":"R-114-1-17","subject":"社會工作研究方法","year":"114","round":"第一次","qno":"17","major":null,"topic":null,"keywords":null,"question":"下列對於個別深入訪談與日常談話的異同敘述，何者正確？","opt_a":"個別深入訪談主要是為了滿足訪談者的要求，因此受訪者必須向訪談者提供有用的資料","opt_b":"日常談話完全沒有目的性，但個別深入訪談具有強烈的目的性","opt_c":"日常談話通常會以友好的打招呼開始，但個別深入訪談會直接開始預定的訪談計畫","opt_d":"個別深入訪談中，通常是由受訪者主導新的話題，訪談者儘可能表現興趣與熱情，鼓勵受訪者暢所欲言","answer":"A","exp_why":null,"exp_others":null,"exp_trap":null,"exp_raw":null,"mnemonic":null,"extension":null,"law":null,"mistake":null,"source_exam_code":"114030","source_url":"https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?c=103&code=114030&q=1&s=0306&t=Q","analysis_status":"review","analysis_attempts":0,"analysis_error":null,"analysis_started_at":null,"analysis_completed_at":null,"legal_status":"not_applicable","legal_checked_at":null,"legal_note":null,"legal_source_url":null,"legal_canonical_names":[],"accepted_answers":null,"grading_mode":"standard","analysis_last_attempt_at":null}]$post$::jsonb;
  item jsonb;observed jsonb;other_before jsonb;other_after jsonb;
  grading_before jsonb;grading_after jsonb;config_before jsonb;config_after jsonb;
  changed integer;
BEGIN
  IF (SELECT count(*) FROM public.questions)<>4800 THEN RAISE EXCEPTION 'SWSI integrated corpus count drift';END IF;
  SELECT jsonb_agg(to_jsonb(q) ORDER BY id) INTO other_before FROM public.questions q WHERE id NOT IN ('DS-108-2-23','R-111-2-14','R-111-2-15','R-111-2-17','R-111-2-18','R-111-2-29','R-111-2-30','R-114-1-17');
  SELECT jsonb_agg(jsonb_build_array(id,answer,accepted_answers,grading_mode) ORDER BY id) INTO grading_before FROM public.questions;
  SELECT to_jsonb(c) INTO config_before FROM public.ai_analysis_job_config c WHERE id=true;
  IF config_before->>'enabled'<>'false' THEN RAISE EXCEPTION 'SWSI integrated AI job config not disabled';END IF;
  FOR item IN SELECT value FROM jsonb_array_elements(before_rows) LOOP
    SELECT to_jsonb(q) INTO STRICT observed FROM public.questions q WHERE id=item->>'id' FOR UPDATE;
    IF observed IS DISTINCT FROM item THEN RAISE EXCEPTION 'SWSI integrated preimage mismatch: %',item->>'id';END IF;
  END LOOP;
  UPDATE public.questions SET question='有關團體工作開始階段的工作重點和工作目標，下列何者正確？①建立團體規範 ②加強正向動機，降低抗拒 ③處理團體成員參與的問題 ④處理成員之間的衝突與緊張 ⑤創造安全與信任關係 ⑥發展溝通、地位、角色與規範的彈性結構 ⑦協助成員感覺自己是團體的一份子 ⑧穩定成員的參與及團體的運作', opt_a='②④⑥⑧' WHERE id='DS-108-2-23';
  GET DIAGNOSTICS changed=ROW_COUNT;
  IF changed<>1 THEN RAISE EXCEPTION 'SWSI integrated row update count: DS-108-2-23'; END IF;
  UPDATE public.questions SET question='情況：某社工想了解北部地區受聘在家中的外籍看護工照顧及生活適應的現況，他設計了一份網路問卷放到外籍移工常聯絡的群組或瀏覽的網站（Facebook 或 Line）上，讓在群組或網站看到此問卷的外籍看護工自由填寫。

承上題，此研究的資料蒐集方法最大的缺點為何？' WHERE id='R-111-2-14';
  GET DIAGNOSTICS changed=ROW_COUNT;
  IF changed<>1 THEN RAISE EXCEPTION 'SWSI integrated row update count: R-111-2-14'; END IF;
  UPDATE public.questions SET question='情況：某社工想了解北部地區受聘在家中的外籍看護工照顧及生活適應的現況，他設計了一份網路問卷放到外籍移工常聯絡的群組或瀏覽的網站（Facebook 或 Line）上，讓在群組或網站看到此問卷的外籍看護工自由填寫。

承上題，若該社工也想要進一步了解北部地區移工失聯的現象，由於受訪對象隱匿（難以尋覓）的特性，下列何種方法適合？' WHERE id='R-111-2-15';
  GET DIAGNOSTICS changed=ROW_COUNT;
  IF changed<>1 THEN RAISE EXCEPTION 'SWSI integrated row update count: R-111-2-15'; END IF;
  UPDATE public.questions SET question='情況：某研究者欲進行全國社會工作師之薪資所得相關因素探究，但研究經費有限。

承上題，該研究之分析單位為何？' WHERE id='R-111-2-17';
  GET DIAGNOSTICS changed=ROW_COUNT;
  IF changed<>1 THEN RAISE EXCEPTION 'SWSI integrated row update count: R-111-2-17'; END IF;
  UPDATE public.questions SET question='情況：某研究者欲進行全國社會工作師之薪資所得相關因素探究，但研究經費有限。

承上題，此一研究可能使用下列何種統計分析方法？' WHERE id='R-111-2-18';
  GET DIAGNOSTICS changed=ROW_COUNT;
  IF changed<>1 THEN RAISE EXCEPTION 'SWSI integrated row update count: R-111-2-18'; END IF;
  UPDATE public.questions SET question='情況：某學者想要針對 4 家平面媒體對於政府開放移工引進臺灣後這 16 年間（1992～2018 年）8,248 則相關報導為母體，研究者先將每篇報導以時間順序排列，形成一個抽樣架構後，以每 4 則抽取一則的方式抽出 2,062 篇新聞報導作為研究樣本，進而整理出臺灣主流媒體報導所塑造的移工形象。

承上題，此研究的分析單位為何？' WHERE id='R-111-2-29';
  GET DIAGNOSTICS changed=ROW_COUNT;
  IF changed<>1 THEN RAISE EXCEPTION 'SWSI integrated row update count: R-111-2-29'; END IF;
  UPDATE public.questions SET question='情況：某學者想要針對 4 家平面媒體對於政府開放移工引進臺灣後這 16 年間（1992～2018 年）8,248 則相關報導為母體，研究者先將每篇報導以時間順序排列，形成一個抽樣架構後，以每 4 則抽取一則的方式抽出 2,062 篇新聞報導作為研究樣本，進而整理出臺灣主流媒體報導所塑造的移工形象。

承上題，這個研究所採用的研究方法為何？' WHERE id='R-111-2-30';
  GET DIAGNOSTICS changed=ROW_COUNT;
  IF changed<>1 THEN RAISE EXCEPTION 'SWSI integrated row update count: R-111-2-30'; END IF;
  UPDATE public.questions SET question='下列對於個別深入訪談與日常談話的異同敘述，何者正確？', opt_a='個別深入訪談主要是為了滿足訪談者的要求，因此受訪者必須向訪談者提供有用的資料', opt_b='日常談話完全沒有目的性，但個別深入訪談具有強烈的目的性', opt_c='日常談話通常會以友好的打招呼開始，但個別深入訪談會直接開始預定的訪談計畫', opt_d='個別深入訪談中，通常是由受訪者主導新的話題，訪談者儘可能表現興趣與熱情，鼓勵受訪者暢所欲言' WHERE id='R-114-1-17';
  GET DIAGNOSTICS changed=ROW_COUNT;
  IF changed<>1 THEN RAISE EXCEPTION 'SWSI integrated row update count: R-114-1-17'; END IF;
  UPDATE public.questions SET analysis_status='review' WHERE id IN ('DS-108-2-23','R-111-2-14','R-111-2-15','R-111-2-17','R-111-2-18','R-111-2-29','R-111-2-30','R-114-1-17') AND analysis_status='pending';
  GET DIAGNOSTICS changed=ROW_COUNT;
  IF changed<>8 THEN RAISE EXCEPTION 'SWSI integrated quarantine row count mismatch';END IF;
  FOR item IN SELECT value FROM jsonb_array_elements(after_rows) LOOP
    SELECT to_jsonb(q) INTO STRICT observed FROM public.questions q WHERE id=item->>'id';
    IF observed IS DISTINCT FROM item THEN RAISE EXCEPTION 'SWSI integrated postimage mismatch: %',item->>'id';END IF;
  END LOOP;
  SELECT jsonb_agg(to_jsonb(q) ORDER BY id) INTO other_after FROM public.questions q WHERE id NOT IN ('DS-108-2-23','R-111-2-14','R-111-2-15','R-111-2-17','R-111-2-18','R-111-2-29','R-111-2-30','R-114-1-17');
  SELECT jsonb_agg(jsonb_build_array(id,answer,accepted_answers,grading_mode) ORDER BY id) INTO grading_after FROM public.questions;
  SELECT to_jsonb(c) INTO config_after FROM public.ai_analysis_job_config c WHERE id=true;
  IF other_before IS DISTINCT FROM other_after THEN RAISE EXCEPTION 'SWSI integrated unrelated-row modified';END IF;
  IF grading_before IS DISTINCT FROM grading_after THEN RAISE EXCEPTION 'SWSI integrated grading changed';END IF;
  IF config_before IS DISTINCT FROM config_after THEN RAISE EXCEPTION 'SWSI integrated AI config changed';END IF;
  IF EXISTS(SELECT 1 FROM public.questions WHERE analysis_status='pending') THEN RAISE EXCEPTION 'SWSI integrated unexpected pending row';END IF;
  RAISE NOTICE 'SWSI integrated 8-row rollback simulation PASS: 4792 other full rows, 4800 grading tuples protected';
END;
$swsi8$;
ROLLBACK;
